"""Thorough pytest suite for md2html.convert."""

import re

import pytest

from md2html import convert


class TestHeadings:
    def test_each_level(self):
        for level in range(1, 7):
            mark = "#" * level
            assert convert(f"{mark} Title {level}") == (
                f"<h{level}>Title {level}</h{level}>"
            )

    def test_no_space_after_hashes_is_not_a_heading(self):
        assert convert("###Title") == "<p>###Title</p>"

    def test_heading_with_inline_formatting(self):
        assert convert("# Hello **world**") == "<h1>Hello <b>world</b></h1>"

    def test_seven_hashes_is_a_paragraph(self):
        assert convert("####### Title") == "<p>####### Title</p>"


class TestParagraphs:
    def test_simple(self):
        assert convert("Hello world") == "<p>Hello world</p>"

    def test_multiline_wraps_into_one_paragraph(self):
        assert convert("line one\nline two") == "<p>line one line two</p>"

    def test_blank_lines_separate_paragraphs(self):
        assert convert("A\n\nB") == "<p>A</p>\n<p>B</p>"

    def test_html_escaped(self):
        assert convert("<script>alert(1)</script>") == (
            "<p>&lt;script&gt;alert(1)&lt;/script&gt;</p>"
        )


class TestBoldAndItalics:
    def test_bold_double_asterisks(self):
        assert convert("a **b** c") == "<p>a <b>b</b> c</p>"

    def test_bold_double_underscores(self):
        assert convert("a __b__ c") == "<p>a <b>b</b> c</p>"

    def test_italic_single_asterisk(self):
        assert convert("a *b* c") == "<p>a <i>b</i> c</p>"

    def test_italic_single_underscore(self):
        assert convert("a _b_ c") == "<p>a <i>b</i> c</p>"

    def test_italic_inside_word_not_italicized(self):
        assert convert("snake_case") == "<p>snake_case</p>"

    def test_bold_inside_italic(self):
        assert convert("*a **b** c*") == "<p><i>a <b>b</b> c</i></p>"

    def test_mixed(self):
        assert convert("**bold** and *italic*") == (
            "<p><b>bold</b> and <i>italic</i></p>"
        )


class TestInlineCode:
    def test_simple(self):
        assert convert("a `x` b") == "<p>a <code>x</code> b</p>"

    def test_code_contents_not_markdown(self):
        assert convert("`**not bold**`") == "<p><code>**not bold**</code></p>"

    def test_code_with_html_escaped(self):
        assert convert("`<i>`") == "<p><code>&lt;i&gt;</code></p>"


class TestFencedCodeBlocks:
    def test_plain_fence(self):
        result = convert("```\nfoo\nbar\n```")
        assert result == "<pre><code>foo\nbar</code></pre>"

    def test_fence_with_language(self):
        result = convert("```python\nprint(1)\n```")
        assert 'class="language-python"' in result
        assert "print(1)" in result

    def test_markdown_inside_code_is_escaped(self):
        result = convert("```\n# not a heading\n**x**\n```")
        assert "<h1>" not in result
        assert "# not a heading" in result
        assert "<b>" not in result

    def test_html_inside_code_is_escaped(self):
        result = convert("```\n<a>\n```")
        assert "&lt;a&gt;" in result

    def test_unclosed_fence_consumes_rest(self):
        result = convert("```\nfoo")
        assert "foo" in result and "<pre" in result


class TestLists:
    def test_unordered_dash(self):
        result = convert("- a\n- b")
        assert result == "<ul>\n<li>a</li>\n<li>b</li>\n</ul>"

    def test_unordered_asterisk(self):
        assert convert("* x\n* y") == "<ul>\n<li>x</li>\n<li>y</li>\n</ul>"

    def test_unordered_plus(self):
        assert convert("+ x\n+ y") == "<ul>\n<li>x</li>\n<li>y</li>\n</ul>"

    def test_ordered(self):
        assert convert("1. a\n2. b") == "<ol>\n<li>a</li>\n<li>b</li>\n</ol>"

    def test_list_items_render_inline_markdown(self):
        assert convert("- **bold** item") == "<ul>\n<li><b>bold</b> item</li>\n</ul>"

    def test_lists_and_paragraph_separated(self):
        result = convert("intro\n\n- a\n- b")
        assert result == "<p>intro</p>\n<ul>\n<li>a</li>\n<li>b</li>\n</ul>"


class TestBlockquotes:
    def test_single_line(self):
        result = convert("> hello")
        assert result == "<blockquote>\n<p>hello</p>\n</blockquote>"

    def test_multi_line(self):
        result = convert("> a\n> b")
        assert result == "<blockquote>\n<p>a b</p>\n</blockquote>"

    def test_contains_paragraph(self):
        result = convert("> one\n>\n> two")
        assert result == "<blockquote>\n<p>one</p>\n<p>two</p>\n</blockquote>"


class TestLinks:
    def test_simple_link(self):
        assert convert("[Google](https://google.com)") == (
            '<p><a href="https://google.com">Google</a></p>'
        )

    def test_link_with_label_and_text(self):
        assert convert("Go to [site](http://x.io) now") == (
            '<p>Go to <a href="http://x.io">site</a> now</p>'
        )

    def test_link_html_escaped(self):
        assert convert("[a](x?b=1&c=2)") == '<p><a href="x?b=1&amp;c=2">a</a></p>'

    def test_link_in_heading(self):
        assert convert("# [Docs](/docs)") == (
            '<h1><a href="/docs">Docs</a></h1>'
        )


class TestCombinations:
    def test_full_document(self):
        md = """# Title

Intro **bold** *italic* `code` and [link](http://a.b).

> quoted words

- one
- two

1. first
2. second

```js
console.log("hi");
```
"""
        result = convert(md)
        assert result == (
            "<h1>Title</h1>\n"
            '<p>Intro <b>bold</b> <i>italic</i> <code>code</code> '
            'and <a href="http://a.b">link</a>.</p>\n'
            "<blockquote>\n<p>quoted words</p>\n</blockquote>\n"
            "<ul>\n<li>one</li>\n<li>two</li>\n</ul>\n"
            "<ol>\n<li>first</li>\n<li>second</li>\n</ol>\n"
            '<pre class="language-js"><code class="language-js">'
            'console.log("hi");</code></pre>'
        )

    def test_empty_string(self):
        assert convert("") == ""

    def test_code_span_stored_safely_when_multiple(self):
        assert convert("`a` then `b`") == "<p><code>a</code> then <code>b</code></p>"


@pytest.mark.parametrize(
    "md,expected",
    [
        ("#", "<p>#</p>"),
        ("**", "<p>**</p>"),
        ("`", "<p><code></p>" if False else "<p>`</p>"),
        ("[broken](no)", '<p><a href="no">broken</a></p>'),
    ],
)
def test_degenerate_inputs(md, expected):
    assert convert(md) == expected


